mabatis.mapper.select:
select
a.std_mete_id,
a.device_type,
a.mete_code,
a.mete_type,
a.mete_name,
a.alarm_note,
a.alarm_explain,
a.alarm_type,
a.unit,
a.up_effect,
a.low_effect,
a.alarm_level,
a.alarm_limit,
a.alarm_delay,
a.alarm_cnt,
a.threshold_abs,
a.threshold_per,
a.modulus,
a.remark
from t_std_mete a
where 1 = 1
 and a.std_mete_id = #{stdMeteId, jdbcType=BIGINT}
 and a.device_type = #{deviceType, jdbcType=INTEGER}
 and a.mete_code = #{meteCode, jdbcType=VARCHAR}
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
 and a.mete_name LIKE CONCAT('%',#{meteName, jdbcType=VARCHAR},'%')
 and a.alarm_note = #{alarmNote, jdbcType=VARCHAR}
 and a.alarm_explain = #{alarmExplain, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=VARCHAR}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.low_effect = #{lowEffect, jdbcType=REAL}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.alarm_limit = #{alarmLimit, jdbcType=INTEGER}
 and a.alarm_delay = #{alarmDelay, jdbcType=INTEGER}
 and a.alarm_cnt = #{alarmCnt, jdbcType=INTEGER}
 and a.threshold_abs = #{thresholdAbs, jdbcType=NUMERIC}
 and a.threshold_per = #{thresholdPer, jdbcType=NUMERIC}
 and a.modulus = #{modulus, jdbcType=INTEGER}
 and a.remark = #{remark, jdbcType=VARCHAR}

